"use client";

import { useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Clock, History, Calendar, UserPlus, LogOut, CreditCard } from "lucide-react";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

export default function HistoryPage() {
  // We can reuse getActiveEncounters or create a specific 'getHistory' query
  const history = useQuery(api.encounters.getActive); 

  return (
    <div className="space-y-8 text-slate-900 animate-in slide-in-from-bottom-4 duration-500 dark:text-slate-100">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-4xl font-black uppercase italic tracking-tighter text-slate-900 dark:text-slate-100">Unit <span className="text-blue-600">History</span></h1>
          <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 dark:text-slate-500">Shift Audit Trail | TEANECK-HACKENSACK HUB</p>
        </div>
        <div className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2 text-[10px] font-black uppercase dark:border-slate-700 dark:bg-slate-900">
          <Calendar className="h-3 w-3 text-blue-600" />
          March 05, 2026
        </div>
      </div>

      <div className="overflow-hidden rounded-[2.5rem] border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900">
        <Table>
          <TableHeader className="bg-slate-50 dark:bg-slate-950/50">
            <TableRow>
              <TableHead className="text-[9px] font-black uppercase tracking-widest pl-8">Event Timestamp</TableHead>
              <TableHead className="text-[9px] font-black uppercase tracking-widest">Activity Type</TableHead>
              <TableHead className="text-[9px] font-black uppercase tracking-widest">Detail</TableHead>
              <TableHead className="text-[9px] font-black uppercase tracking-widest">Status</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {history?.map((entry, i) => (
              <TableRow key={entry._id} className="transition-colors hover:bg-slate-50/50 dark:hover:bg-slate-800/30">
                <TableCell className="pl-8 font-mono text-[10px] text-slate-400 dark:text-slate-500">
                  {new Date(entry._creationTime).toLocaleTimeString()}
                </TableCell>
                <TableCell>
                  <div className="flex items-center gap-2">
                    {i % 3 === 0 ? <UserPlus className="h-3 w-3 text-blue-500" /> : <CreditCard className="h-3 w-3 text-emerald-500" />}
                    <span className="text-[10px] font-black uppercase italic text-slate-700 dark:text-slate-200">
                      {i % 3 === 0 ? "Admission" : "POS Collection"}
                    </span>
                  </div>
                </TableCell>
                <TableCell className="text-[10px] font-bold uppercase text-slate-500 dark:text-slate-300">
                  {entry.patientName} - {i % 3 === 0 ? "Triage Complete" : "Co-pay Logged"}
                </TableCell>
                <TableCell>
                  <div className="h-1.5 w-1.5 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]" />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { 
  LayoutDashboard, 
  ShieldCheck, 
  History, 
  ArrowLeft,
  BarChart4,
  Users2,
  ScrollText,
  FolderCog
} from "lucide-react";
import ShiftHandoffModal from "@/components/mgmt/ShiftHandoffModal";

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();

  const navItems = [
    { name: "Command Center", href: "/dashboard/admin", icon: LayoutDashboard },
    { name: "Staff Management", href: "/dashboard/admin/staff", icon: Users2 },
    { name: "Identity Audit", href: "/dashboard/admin/audit", icon: ShieldCheck },
    { name: "Security Audit", href: "/dashboard/admin/security", icon: ScrollText },
    { name: "Documents Policy", href: "/dashboard/admin/documents", icon: FolderCog },
    { name: "Revenue Reports", href: "/dashboard/admin/revenue", icon: BarChart4 },
    { name: "Unit History", href: "/dashboard/admin/history", icon: History },
  ];

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      {/* SLIM ADMIN SIDEBAR */}
      <aside className="w-20 lg:w-64 bg-slate-900 flex flex-col transition-all duration-300">
        <div className="p-6">
          <Link href="/" className="flex items-center gap-3 group">
            <div className="p-2 bg-blue-600 rounded-xl group-hover:bg-blue-500 transition-colors">
              <ArrowLeft className="h-4 w-4 text-white" />
            </div>
            <span className="hidden lg:block text-[10px] font-black text-slate-400 uppercase tracking-widest">
              Back to Clinical
            </span>
          </Link>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => {
            const isActive = pathname === item.href;
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`flex items-center gap-4 px-4 py-4 rounded-2xl transition-all group ${
                  isActive 
                    ? "bg-blue-600 text-white shadow-lg shadow-blue-900/20" 
                    : "text-slate-500 hover:bg-slate-800 hover:text-slate-300"
                }`}
              >
                <item.icon className={`h-5 w-5 ${isActive ? "text-white" : "group-hover:scale-110 transition-transform"}`} />
                <span className={`hidden lg:block text-[10px] font-black uppercase tracking-widest ${isActive ? "text-white" : ""}`}>
                  {item.name}
                </span>
              </Link>
            );
          })}
        </nav>

        <div className="p-6 border-t border-slate-800">
          <div className="flex items-center gap-3">
            <div className="h-8 w-8 rounded-full bg-slate-700 flex items-center justify-center border border-slate-600">
              <span className="text-[10px] font-black text-slate-300">SR</span>
            </div>
            <div className="hidden lg:block">
              <p className="text-[9px] font-black text-slate-200 uppercase tracking-tighter leading-none">Sophia Ramirez</p>
              <p className="text-[8px] font-bold text-slate-500 uppercase mt-1 italic">Unit Coordinator</p>
            </div>
          </div>
        </div>
      </aside>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 overflow-y-auto">
        <div className="p-4 lg:p-8">
          {children}
        </div>
      </main>
    </div>
  );
}

"use client";

import { useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import { BarChart3, TrendingUp, DollarSign, ArrowUpRight, ArrowDownRight, CreditCard } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import RevenuePayerMix from "@/components/mgmt/RevenuePayerMix";

interface RevenueCardProps {
  title: string;
  value: string | number;
  trend: string;
  trendUp: boolean;
}

export default function RevenuePage() {
  const stats = useQuery(api.encounters.getERStats);

  // Simulated payer mix for the chart
  const payerMix = [
    { name: "Horizon BCBS", count: 42, color: "bg-blue-600" },
    { name: "United Healthcare", count: 25, color: "bg-emerald-600" },
    { name: "Medicare", count: 28, color: "bg-purple-600" },
    { name: "Self-Pay", count: 10, color: "bg-amber-500" },
  ];

  return (
    <div className="space-y-8 text-slate-900 animate-in fade-in duration-500 dark:text-slate-100">
      <div>
        <h1 className="text-4xl font-black uppercase italic tracking-tighter text-slate-900 dark:text-slate-100">Revenue <span className="text-blue-600">Analytics</span></h1>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 dark:text-slate-500">Fiscal Year 2026 | Unit 4B Performance</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <RevenueCard title="Net Collections" value={`$${stats?.dailyRevenue || 0}`} trend="+12.5%" trendUp={true} />
        <RevenueCard title="Avg. Reimbursement" value="$1,840" trend="-2.1%" trendUp={false} />
        <RevenueCard title="Clean Claim Rate" value="98.4%" trend="+0.5%" trendUp={true} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <RevenuePayerMix payerData={payerMix} />
        <Card className="rounded-[2.5rem] border-slate-200 bg-white p-8 dark:border-slate-800 dark:bg-slate-900">
          <h3 className="mb-6 text-xs font-black uppercase italic tracking-widest text-slate-400 dark:text-slate-500">Shift Collection Velocity</h3>
          <div className="h-64 flex items-end gap-2 px-4">
            {[40, 70, 45, 90, 65, 80, 95].map((h, i) => (
              <div key={i} className="group relative flex-1 rounded-t-lg bg-slate-100 transition-colors hover:bg-blue-100 dark:bg-slate-800 dark:hover:bg-blue-950/40">
                <div className="absolute bottom-0 w-full bg-blue-600 rounded-t-lg transition-all duration-1000" style={{ height: `${h}%` }} />
                <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-[8px] font-bold text-slate-400 opacity-0 group-hover:opacity-100 dark:text-slate-500">0{i+1}:00</span>
              </div>
            ))}
          </div>
          <p className="mt-4 text-center text-[9px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Hourly Cash Capture (Current Shift)</p>
        </Card>
      </div>
    </div>
  );
}

function RevenueCard({ title, value, trend, trendUp }: RevenueCardProps) {
  return (
    <Card className="rounded-[2rem] border-slate-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900">
      <p className="mb-1 text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">{title}</p>
      <div className="flex items-baseline gap-3">
        <h2 className="text-3xl font-black italic tracking-tighter text-slate-900 dark:text-slate-100">{value}</h2>
        <div className={`flex items-center text-[10px] font-black ${trendUp ? 'text-emerald-500' : 'text-red-500'}`}>
          {trendUp ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}
          {trend}
        </div>
      </div>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useMutation } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { 
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter 
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { PlusCircle, FlaskConical, Save, AlertCircle } from "lucide-react";
import { toast } from "sonner";

export default function AddLabResult({ encounterId }: { encounterId: Id<"encounters"> }) {
  const [open, setOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  
  // Form State
  const [testName, setTestName] = useState("");
  const [value, setValue] = useState("");
  const [unit, setUnit] = useState("");
  const [range, setRange] = useState("");
  const [isAbnormal, setIsAbnormal] = useState(false);

  const postResult = useMutation(api.labs.postResult);

  const handleSubmit = async () => {
    if (!testName || !value) return;
    setIsSaving(true);
    
    try {
      await postResult({
        encounterId,
        testName,
        value,
        unit,
        range,
        isAbnormal,
        status: "final"
      });
      toast.success(`${testName} Resulted`, {
        description: `Value of ${value} ${unit} added to clinical chart.`
      });
      setOpen(false);
      resetForm();
    } catch (e) {
      toast.error("Entry Failed", { description: "Check server connection." });
    } finally {
      setIsSaving(false);
    }
  };

  const resetForm = () => {
    setTestName("");
    setValue("");
    setUnit("");
    setRange("");
    setIsAbnormal(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" className="bg-indigo-600 hover:bg-indigo-700 text-[10px] font-black uppercase tracking-widest gap-2">
          <PlusCircle className="h-3.5 w-3.5" /> Post Result
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-106.25 rounded-3xl">
        <DialogHeader>
          <DialogTitle className="text-sm font-black uppercase tracking-[0.2em] flex items-center gap-2">
            <FlaskConical className="h-4 w-4 text-indigo-600" /> POC Lab Entry
          </DialogTitle>
        </DialogHeader>

        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right text-[10px] font-bold uppercase text-slate-400">Test</Label>
            <Input 
              placeholder="e.g., Troponin I" 
              className="col-span-3 h-9 text-sm font-bold bg-slate-50 border-none rounded-xl"
              value={testName}
              onChange={(e) => setTestName(e.target.value)}
            />
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right text-[10px] font-bold uppercase text-slate-400">Value</Label>
            <Input 
              placeholder="12.4" 
              className="col-span-3 h-9 text-sm font-bold bg-slate-50 border-none rounded-xl"
              value={value}
              onChange={(e) => setValue(e.target.value)}
            />
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right text-[10px] font-bold uppercase text-slate-400">Unit/Range</Label>
            <div className="col-span-3 flex gap-2">
              <Input 
                placeholder="mg/dL" 
                className="h-9 text-sm bg-slate-50 border-none rounded-xl"
                value={unit}
                onChange={(e) => setUnit(e.target.value)}
              />
              <Input 
                placeholder="0-0.4" 
                className="h-9 text-sm bg-slate-50 border-none rounded-xl"
                value={range}
                onChange={(e) => setRange(e.target.value)}
              />
            </div>
          </div>
          
          <div className="flex items-center justify-between bg-slate-50 p-4 rounded-2xl border border-slate-100">
            <div className="flex items-center gap-2">
              <AlertCircle className={`h-4 w-4 ${isAbnormal ? 'text-red-500 animate-pulse' : 'text-slate-300'}`} />
              <Label className="text-[10px] font-black uppercase text-slate-600">Mark as Abnormal?</Label>
            </div>
            <Switch 
              checked={isAbnormal} 
              onCheckedChange={setIsAbnormal}
              className="data-[state=checked]:bg-red-500" 
            />
          </div>
        </div>

        <DialogFooter>
          <Button 
            onClick={handleSubmit} 
            disabled={isSaving || !testName || !value}
            className="w-full bg-slate-900 hover:bg-black font-black uppercase text-[10px] tracking-widest h-12 rounded-2xl gap-2"
          >
            {isSaving ? "Processing..." : <><Save className="h-4 w-4" /> Sign & Result</>}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useRef } from "react";
import { useMutation, useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { useReactToPrint } from "react-to-print";

// UI Components
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";

// Icons
import { 
  Printer, 
  LogOut, 
  CalendarDays, 
  PenTool,
  Eraser
} from "lucide-react";
import SignatureCanvas from "react-signature-canvas";

export default function DischargeSummary({ encounterId }: { encounterId: Id<"encounters"> }) {
  const [summary, setSummary] = useState("");
  const [followUpDate, setFollowUpDate] = useState("");
  const [signatureData, setSignatureData] = useState<string | null>(null);
  
  const printRef = useRef<HTMLDivElement>(null);
  const sigPad = useRef<SignatureCanvas>(null);

  // DATA QUERIES
  const encounter = useQuery(api.encounters.getById, encounterId ? { encounterId } : "skip");
  const patient = useQuery(api.patients.getById, encounter?.patientId ? { patientId: encounter.patientId } : "skip");
  const lastVitals = useQuery(api.vitals.getHistory, encounterId ? { encounterId } : "skip");
  const prescribedMeds = useQuery(api.medications.getByEncounter, encounterId ? { encounterId } : "skip");
  const finalizeDischarge = useMutation(api.encounters.dischargePatient);

  const handlePrint = useReactToPrint({
    contentRef: printRef,
    documentTitle: `Discharge_Summary_${patient?.name || "Patient"}`,
  });

  const clearSignature = () => {
    sigPad.current?.clear();
    setSignatureData(null);
  };

  const saveSignature = () => {
    if (sigPad.current?.isEmpty()) {
      toast.error("Please provide a signature first.");
      return;
    }
    setSignatureData(sigPad.current?.getTrimmedCanvas().toDataURL("image/png") || null);
    toast.success("Signature captured.");
  };

  const generateTemplate = () => {
    if (!encounter || !patient) return toast.error("Clinical records not fully loaded.");

    const latest = lastVitals?.[lastVitals.length - 1];
    const homeMeds = prescribedMeds && prescribedMeds.length > 0 
      ? prescribedMeds.filter(m => m.status !== "held").map((m) => `• ${m.name} ${m.dosage} (${m.route})`).join('\n')
      : "No new medications prescribed. Continue current home regimen.";

    const dateString = followUpDate 
      ? new Date(followUpDate).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })
      : "[DATE NOT SPECIFIED]";

    const template = `------------------------------------------------------------
OFFICIAL PATIENT DISCHARGE INSTRUCTIONS
------------------------------------------------------------
FACILITY: Hackensack Meridian ER - Unit 4B
PATIENT: ${patient.name}
MRN: ${patient.mrn}
DATE: ${new Date().toLocaleDateString()}

REASON FOR VISIT: ${encounter.chiefComplaint}

CLINICAL STATUS AT DISCHARGE:
Heart Rate: ${latest?.hr || '--'} BPM | SpO2: ${latest?.spO2 || '--'}%

HOME MEDICATIONS & INSTRUCTIONS:
${homeMeds}

FOLLOW-UP CARE:
>>> SCHEDULED FOLLOW-UP: ${dateString} <<<

RED FLAGS: Return to ER for chest pain, shortness of breath, or high fever.
------------------------------------------------------------`;
    
    setSummary(template);
  };

  return (
    <div className="space-y-6">
      {/* SETTINGS & SIGNATURE CAPTURE (Hidden in Print) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 no-print">
        <Card className="border-emerald-200 bg-emerald-50/20">
          <CardContent className="pt-6 space-y-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black uppercase text-emerald-800 flex items-center gap-1.5 tracking-widest">
                <CalendarDays className="h-3 w-3" /> Follow-Up Date
              </label>
              <Input type="date" value={followUpDate} onChange={(e) => setFollowUpDate(e.target.value)} className="bg-white" />
            </div>
            <Button onClick={generateTemplate} className="w-full bg-emerald-600 hover:bg-emerald-700 font-black uppercase text-[10px] tracking-widest">
              Generate Template
            </Button>
          </CardContent>
        </Card>

        <Card className="border-blue-200 bg-blue-50/20">
          <CardContent className="pt-6 space-y-2">
            <label className="text-[10px] font-black uppercase text-blue-800 flex items-center gap-1.5 tracking-widest">
              <PenTool className="h-3 w-3" /> Patient Acknowledgment Signature
            </label>
            <div className="bg-white border-2 border-blue-100 rounded-xl overflow-hidden">
              <SignatureCanvas 
                ref={sigPad}
                penColor="black"
                canvasProps={{ className: "w-full h-24" }}
              />
            </div>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={clearSignature} className="flex-1 text-[10px] font-bold uppercase">
                <Eraser className="h-3 w-3 mr-2"/> Clear</Button>
              <Button size="sm" onClick={saveSignature} className="flex-1 bg-blue-600 text-[10px] font-bold uppercase tracking-widest">Confirm Sig</Button>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* THE PRINTABLE DOCUMENT */}
      
      <Card className="border-slate-900 border-t-8 shadow-2xl relative print:shadow-none">
        <CardContent className="pt-10 p-12" ref={printRef}>
          <div className="hidden print:block border-b-2 border-black pb-4 mb-8">
            <h1 className="text-2xl font-black uppercase tracking-tighter">Hackensack Meridian Health</h1>
            <p className="text-xs font-bold uppercase text-slate-500 italic">Official Clinical Record</p>
          </div>

          <Textarea 
            value={summary}
            onChange={(e) => setSummary(e.target.value)}
            className="min-h-100 font-mono text-xs border-none leading-relaxed bg-transparent resize-none print:text-[11pt]"
          />

          {/* SIGNATURE DISPLAY ON THE DOCUMENT */}
          <div className="mt-12 border-t-2 border-slate-100 pt-8 flex justify-between items-end">
            <div className="space-y-1">
              <p className="text-[10px] font-black uppercase text-slate-400">Electronic Validation</p>
              <p className="text-[9px] font-mono text-slate-400">UUID: {encounterId.slice(0,12)}</p>
            </div>
            
            <div className="text-center">
              {signatureData ? (
                <img src={signatureData} alt="Patient Signature" className="h-16 mx-auto mb-1" />
              ) : (
                <div className="h-16 w-48 border-b border-dashed border-slate-300 mb-1 flex items-center justify-center">
                  <span className="text-[9px] text-slate-300 uppercase font-black">Waiting for signature...</span>
                </div>
              )}
              <p className="text-[10px] font-black uppercase border-t border-slate-900 pt-1">Patient/Guardian Signature</p>
            </div>
          </div>
        </CardContent>

        {/* Action Footer (Hidden in Print) */}
        <div className="mt-8 flex flex-col md:flex-row justify-between items-center gap-4 border-t pt-6 border-slate-100 no-print">
          
          {/* UTILIZING THE ALERT CIRCLE HELPER */}
          <div className="flex items-start gap-3 max-w-100 bg-slate-50 p-3 rounded-xl border border-slate-100">
            <AlertCircle className="h-5 w-5 text-amber-500 mt-0.5 shrink-0" />
            <div className="space-y-1">
              <p className="text-[10px] font-black uppercase text-slate-600 tracking-tight">Clinical Verification Required</p>
              <p className="text-[9px] text-slate-500 leading-tight italic">
                By clicking &quot;Finalize,&quot; you certify that the Red Flags and follow-up instructions 
                were reviewed verbally with the patient and they expressed understanding.
              </p>
            </div>
          </div>

          <div className="flex gap-3 w-full md:w-auto">
            <Button 
              variant="outline" 
              onClick={() => handlePrint()} 
              disabled={!summary || !signatureData}
              className="flex-1 md:flex-none gap-2 font-black uppercase text-[10px] tracking-widest border-slate-300"
            >
              <Printer className="h-3.5 w-3.5" /> Print Signed PDF
            </Button>
            <Button 
              onClick={async () => {
                await finalizeDischarge({ encounterId, summary });
                toast.success("Record Finalized & Locked");
              }} 
              disabled={!summary || !signatureData}
              className="flex-1 md:flex-none bg-slate-900 hover:bg-black gap-2 font-black uppercase text-[10px] tracking-widest px-8 shadow-xl transition-all active:scale-95"
            >
              <LogOut className="h-3.5 w-3.5 text-emerald-400" /> Finalize Encounter
            </Button>
          </div>
        </div>
      </Card>

      <style jsx global>{`
        @media print {
          .no-print { display: none !important; }
          body { background: white !important; padding: 0 !important; }
          textarea { border: none !important; box-shadow: none !important; }
        }
      `}</style>
    </div>
  );
}

// Small helper for instructions
function AlertCircle({ className }: { className?: string }) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
      <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
    </svg>
  );
}

