"use client";

import { useQuery, useMutation } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { 
  Scan, 
  CheckCircle2, 
  FileSearch,
  ChevronRight,
  FlaskConical,
  Activity
} from "lucide-react";
import { Button } from "./ui/button";
import PlaceImagingOrder from "./PlaceImagingOrder";
import { toast } from "sonner";
import ViewImagingReport from "./ViewImagingReport";

export default function ImagingOrders({
  encounterId,
  actorName,
}: {
  encounterId: Id<"encounters">;
  actorName?: string;
}) {
  const orders = useQuery(api.imaging.getByEncounter, { encounterId });
  const finalizeSimulatedResult = useMutation(api.imaging.finalizeSimulatedResult);

  const handleSimulateResult = async (orderId: Id<"imagingOrders">) => {
    try {
      await finalizeSimulatedResult({ orderId });
      toast.success("Radiology Report Finalized");
    } catch (e) {
      toast.error("Simulation failed");
    }
  };

  if (orders === undefined) return (
    <div className="h-40 w-full bg-slate-50 animate-pulse rounded-2xl flex items-center justify-center">
      <Activity className="h-6 w-6 text-slate-300 animate-spin" />
    </div>
  );

  return (
    <div className="space-y-4">
      <div className="bg-white rounded-2xl border border-slate-200 p-5 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2">
          <Scan className="h-5 w-5 text-blue-600" />
          <div>
            <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-600 leading-none">Radiology Tracking</h3>
            <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">CPOE & PACS Integration</p>
          </div>
        </div>
        <PlaceImagingOrder encounterId={encounterId} orderedBy={actorName} />
      </div>

      {orders.length === 0 && (
        <div className="text-center py-20 bg-slate-50/10 border-2 border-dashed rounded-3xl border-slate-200">
          <Scan className="h-10 w-10 text-slate-200 mx-auto mb-3" />
          <p className="text-xs font-black text-slate-400 uppercase tracking-widest">No Radiology Orders Found</p>
        </div>
      )}

      {orders.map((order) => (
        <Card key={order._id} className="border-slate-200 overflow-hidden shadow-sm hover:border-blue-200 transition-all bg-white">
          <CardContent className="p-0">
            <div className="flex items-stretch">
              <div className={`w-1.5 ${
                order.status === 'Resulted' ? 'bg-emerald-500' : 
                order.status === 'In Progress' ? 'bg-blue-500 animate-pulse' : 'bg-slate-300'
              }`} />
              
              <div className="flex-1 p-5">
                <div className="flex justify-between items-start mb-4">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <Badge className={`text-[9px] font-black uppercase ${
                        order.priority === 'STAT' ? "bg-red-100 text-red-700 border-none animate-pulse" : "bg-slate-100 text-slate-600"
                      }`}>
                        {order.priority}
                      </Badge>
                      <span className="text-sm font-black text-slate-800 tracking-tight">{order.studyName}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Indication: {order.reason}</p>
                  </div>
                  <div className="text-right">
                    <span className="text-[10px] font-mono font-bold text-slate-400 block mb-1">
                      {new Date(order.orderedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                    <Badge variant="outline" className="text-[8px] font-black text-blue-600 border-blue-100 uppercase">{order.modality}</Badge>
                  </div>
                </div>

                <div className="flex items-center justify-between bg-slate-50/50 p-3 rounded-xl border border-slate-100">
                  <div className="flex items-center gap-6">
                    {['Ordered', 'In Progress', 'Resulted'].map((step, i) => (
                      <div key={step} className="flex items-center gap-2">
                        <div className={`h-2 w-2 rounded-full ${
                          (step === order.status) ? 'bg-blue-500 ring-4 ring-blue-100' : 
                          (i < ['Ordered', 'In Progress', 'Resulted'].indexOf(order.status)) ? 'bg-emerald-500' : 'bg-slate-200'
                        }`} />
                        <span className="text-[9px] font-black text-slate-600 uppercase">{step}</span>
                        {i < 2 && <ChevronRight className="h-3 w-3 text-slate-300" />}
                      </div>
                    ))}
                  </div>

                  <div className="flex gap-2">
                    {order.status !== 'Resulted' && (
                      <Button 
                        onClick={() => handleSimulateResult(order._id)}
                        variant="outline" size="sm" 
                        className="h-7 text-[9px] font-black uppercase text-slate-400 border-slate-100 hover:bg-emerald-50 hover:text-emerald-600"
                      >
                        <FlaskConical className="h-3 w-3 mr-1" /> Simulate Result
                      </Button>
                    )}
                    {order.status === 'Resulted' && (
                      <ViewImagingReport 
                        orderId={order._id}
                        studyName={order.studyName}
                        modality={order.modality}
                        report={order.report}
                        orderingPhysician={order.orderedBy}
                        simulatedSeries={order.simulatedSeries}
                        resultedAt={order.orderedAt}
                      />
                    )}
                  </div>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

"use client";

import { useQuery, useMutation } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { CheckCircle2, Clock, UserCircle } from "lucide-react";
import { toast } from "sonner";

interface MedHistoryProps {
  encounterId: Id<"encounters">;
}

export default function MedicationHistory({ encounterId }: MedHistoryProps) {
  // 1. Fetch medications for this encounter
  const medications = useQuery(api.medications.getByEncounter, { encounterId });
  const administerMed = useMutation(api.medications.administer);

  if (!medications) return <div className="animate-pulse h-20 bg-slate-50 rounded-xl" />;

  const handleAdminister = async (id: Id<"medications">) => {
    try {
      await administerMed({ medicationId: id });
      toast.success("Medication Documented", {
        description: "Status updated to Administered by Sophia R, RN",
      });
    } catch (error) {
      toast.error("Documentation Error");
    }
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
      <div className="bg-slate-50 px-4 py-3 border-b border-slate-200 flex justify-between items-center">
        <h3 className="text-xs font-black uppercase tracking-widest text-slate-500 flex items-center gap-2">
          <Clock className="h-4 w-4" /> eMAR / Medication History
        </h3>
      </div>
      
      <Table>
        <TableHeader className="bg-slate-50/50">
          <TableRow>
            <TableHead className="text-[10px] uppercase font-bold">Medication</TableHead>
            <TableHead className="text-[10px] uppercase font-bold">Order Details</TableHead>
            <TableHead className="text-[10px] uppercase font-bold">Ordered By</TableHead>
            <TableHead className="text-[10px] uppercase font-bold">Status</TableHead>
            <TableHead className="text-right text-[10px] uppercase font-bold">Action</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {medications.length === 0 ? (
            <TableRow>
              <TableCell colSpan={5} className="text-center py-8 text-slate-400 text-xs italic">
                No medication orders found for this encounter.
              </TableCell>
            </TableRow>
          ) : (
            medications.map((med) => (
              <TableRow key={med._id} className="hover:bg-slate-50/50 transition-colors">
                <TableCell className="font-bold text-slate-900">{med.name}</TableCell>
                <TableCell>
                  <div className="text-xs text-slate-600 font-medium">
                    {med.dosage} • {med.route}
                  </div>
                </TableCell>
                <TableCell>
                  <div className="flex items-center gap-1 text-[11px] text-slate-500">
                    <UserCircle className="h-3 w-3" /> {med.orderedBy}
                  </div>
                </TableCell>
                <TableCell>
                  {med.status === "administered" ? (
                    <Badge className="bg-emerald-50 text-emerald-700 border-emerald-200 gap-1 hover:bg-emerald-50">
                      <CheckCircle2 className="h-3 w-3" /> Administered
                    </Badge>
                  ) : (
                    <Badge variant="outline" className="text-amber-600 border-amber-200 bg-amber-50/50">
                      Pending
                    </Badge>
                  )}
                </TableCell>
                <TableCell className="text-right">
                  {med.status !== "administered" && (
                    <Button 
                      size="sm" 
                      onClick={() => handleAdminister(med._id)}
                      className="bg-blue-600 hover:bg-blue-700 h-7 text-[10px] px-3 font-bold"
                    >
                      Administer
                    </Button>
                  )}
                  {med.status === "administered" && (
                    <span className="text-[10px] font-bold text-slate-400 italic">
                      {med.adminBy}
                    </span>
                  )}
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useMutation } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogTrigger 
} from "@/components/ui/dialog";
import { checkAllergyConflict } from "@/lib/safety";
import { AlertCircle, PlusCircle, PenTool, ShieldAlert } from "lucide-react";
import { toast } from "sonner";

interface OrderProps {
  encounterId: Id<"encounters">;
  patientId: Id<"patients">;
  patientAllergies: string[];
}

const HIGH_ALERT_MEDS = ["Insulin", "Heparin", "Warfarin", "Fentanyl", "Morphine", "Amiodarone"];

export default function OrderMedication({ encounterId, patientId, patientAllergies }: OrderProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [medName, setMedName] = useState("");
  const [dosage, setDosage] = useState("");
  const [route, setRoute] = useState("IV");
  
  const createOrder = useMutation(api.medications.createOrder);
  const { hasConflict, allergen } = checkAllergyConflict(patientAllergies, medName);

  const isHighAlert = HIGH_ALERT_MEDS.some(m => 
    medName.toLowerCase().includes(m.toLowerCase())
  );

  const handleOrder = async () => {
    try {
      await createOrder({
        patientId,
        encounterId,
        name: medName,
        dosage,
        route,
        orderedBy: "Dr. Sophia Amanda Ramirez, MD", // Authenticated signature
      });
      
      toast.success("Order Signed & Sent", {
        description: `${medName} ${dosage} ${route} has been added to the eMAR.`,
      });
      
      setIsOpen(false);
      setMedName("");
      setDosage("");
    } catch (error) {
      toast.error("Order Entry Failed", {
        description: "Please check clinical connectivity and try again.",
      });
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button
          variant="outline"
          className="gap-2 border-blue-200 text-blue-700 hover:bg-blue-50 transition-all dark:border-blue-500/40 dark:bg-blue-950/30 dark:text-blue-200 dark:hover:bg-blue-900/40"
        >
          <PlusCircle className="h-4 w-4" /> New Medication Order
        </Button>
      </DialogTrigger>
      
      <DialogContent className="sm:max-w-106.25 border-t-4 border-t-blue-600 dark:border-slate-700 dark:border-t-blue-500">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-slate-900 dark:text-slate-100">
            <PenTool className="h-5 w-5 text-blue-600 dark:text-blue-400" />
            <span className="rounded-md bg-blue-50 px-2 py-1 text-[13px] font-black tracking-tight text-blue-800 dark:bg-blue-500/20 dark:text-blue-100">
              Computerized Provider Order Entry (CPOE)
            </span>
          </DialogTitle>
        </DialogHeader>
        
        <div className="grid gap-4 py-4">
          {/* Order Summary Preview */}
          {medName && dosage && (
            <div className={`p-3 rounded-lg border flex flex-col gap-1 ${isHighAlert ? 'bg-orange-50 border-orange-200' : 'bg-blue-50 border-blue-200'}`}>
              <div className="flex justify-between items-center">
                <p className={`text-[10px] font-black uppercase tracking-widest ${isHighAlert ? 'text-orange-600' : 'text-blue-600'}`}>
                  {isHighAlert ? "High-Alert Order Summary" : "Order Summary"}
                </p>
                {isHighAlert && <ShieldAlert className="h-3 w-3 text-orange-600 animate-pulse" />}
              </div>
              <p className="text-sm font-bold text-slate-900">
                {medName} {dosage} {route}
              </p>
            </div>
          )}

          <div className="space-y-2">
            <label className="text-xs font-black uppercase text-slate-500 tracking-wider">Medication Name</label>
            <Input 
              placeholder="e.g. Aspirin" 
              value={medName} 
              onChange={(e) => setMedName(e.target.value)}
              className={hasConflict ? "border-red-500 focus-visible:ring-red-500 bg-red-50/30" : "bg-slate-50/50"}
            />
            {hasConflict && (
              <div className="flex items-center gap-2 text-red-600 bg-red-50 p-2 rounded-md text-[11px] font-bold border border-red-100">
                <AlertCircle className="h-4 w-4 shrink-0" />
                CONTRAINDICATION: Patient allergic to {allergen}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-black uppercase text-slate-500 tracking-wider">Dosage</label>
              <Input 
                placeholder="e.g. 325mg" 
                value={dosage} 
                onChange={(e) => setDosage(e.target.value)} 
                className="bg-slate-50/50"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-black uppercase text-slate-500 tracking-wider">Route</label>
              <select 
                className="h-10 w-full rounded-md border bg-slate-50/50 px-3 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
                value={route}
                onChange={(e) => setRoute(e.target.value)}
              >
                <option value="PO" className="bg-white text-slate-900 dark:bg-slate-900 dark:text-slate-100">PO (Oral)</option>
                <option value="IV" className="bg-white text-slate-900 dark:bg-slate-900 dark:text-slate-100">IV</option>
                <option value="IM" className="bg-white text-slate-900 dark:bg-slate-900 dark:text-slate-100">IM</option>
                <option value="SubQ" className="bg-white text-slate-900 dark:bg-slate-900 dark:text-slate-100">SubQ</option>
                <option value="PR" className="bg-white text-slate-900 dark:bg-slate-900 dark:text-slate-100">PR (Rectal)</option>
              </select>
            </div>
          </div>

          {/* Electronic Signature Block */}
          <div className="mt-2 rounded-lg border border-dashed border-slate-300 bg-slate-50 p-3 dark:border-blue-400/40 dark:bg-blue-950/30">
            <p className="mb-1 text-[9px] font-black uppercase tracking-tighter text-slate-500 dark:text-blue-200">Legal Attestation & Signature</p>
            <p className="text-sm font-serif italic text-slate-800 dark:text-slate-100">Sophia Amanda Ramirez, MD</p>
            <p className="mt-1 text-[9px] text-slate-500 dark:text-blue-200/90">
              Time: {new Date().toLocaleTimeString()} | ID: SAR-2026-CCMA
            </p>
          </div>
        </div>

        <div className="flex justify-end gap-3 pt-2">
          <Button variant="ghost" onClick={() => setIsOpen(false)} className="text-slate-500">
            Discard
          </Button>
          <Button 
            onClick={handleOrder} 
            disabled={!medName || !dosage || hasConflict}
            className={`font-bold ${
              isHighAlert 
                ? "bg-orange-600 hover:bg-orange-700 text-white shadow-orange-100 shadow-lg" 
                : "bg-blue-600 hover:bg-blue-700 text-white"
            }`}
          >
            {isHighAlert ? "Sign High-Alert Order" : "Sign & Send Order"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useQuery, useMutation } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Home, Cigarette, Wine, ClipboardCheck, Plus, Trash2, CheckCircle2 } from "lucide-react";
import { toast } from "sonner";
import { useResolvedActor } from "@/lib/hooks/useResolvedActor";

export default function PatientCareSidebar({ 
  patientId, 
  encounterId,
  onOpenPatientInfo,
}: { 
  patientId: Id<"patients">; 
  encounterId: Id<"encounters">; 
  onOpenPatientInfo?: () => void;
}) {
  const { actorName, actorRole } = useResolvedActor();
  const social = useQuery(api.socialHistory.getByPatient, { patientId });
  const tasks = useQuery(api.checklists.getByEncounter, { encounterId });
  const toggleTask = useMutation(api.checklists.toggle);
  const createTask = useMutation(api.checklists.create);
  const removeTask = useMutation(api.checklists.remove);
  const clearCompleted = useMutation(api.checklists.clearCompleted);
  const [addingTask, setAddingTask] = useState(false);
  const [newTaskText, setNewTaskText] = useState("");

  const checklistSummary = useMemo(() => {
    const total = tasks?.length ?? 0;
    const completed = tasks?.filter((task) => task.completed).length ?? 0;
    const pending = Math.max(0, total - completed);
    const percent = total === 0 ? 0 : Math.round((completed / total) * 100);
    return { total, completed, pending, percent };
  }, [tasks]);

  const handleToggle = async (taskId: Id<"checklists">) => {
    try {
      await toggleTask({
        taskId,
        completedBy: actorName,
        completedByRole: actorRole,
      });
      toast.success("Care task updated");
    } catch (e) {
      toast.error("Failed to update task");
    }
  };

  const handleCreateTask = async () => {
    const taskText = newTaskText.trim();
    if (taskText.length < 3) {
      toast.error("Checklist item must be at least 3 characters.");
      return;
    }

    try {
      await createTask({ encounterId, item: taskText });
      setNewTaskText("");
      setAddingTask(false);
      toast.success("Checklist item added.");
    } catch (error) {
      const message = error instanceof Error ? error.message : "Unable to add checklist item.";
      toast.error(message);
    }
  };

  const handleRemoveTask = async (taskId: Id<"checklists">) => {
    try {
      await removeTask({ taskId });
      toast.success("Checklist item removed.");
    } catch {
      toast.error("Unable to remove checklist item.");
    }
  };

  const handleClearCompleted = async () => {
    if (checklistSummary.completed === 0) {
      toast.error("No completed tasks to clear.");
      return;
    }

    try {
      const result = await clearCompleted({ encounterId });
      toast.success(`Removed ${result.removedCount} completed task${result.removedCount === 1 ? "" : "s"}.`);
    } catch {
      toast.error("Unable to clear completed tasks.");
    }
  };

  return (
    <div className="space-y-6">
      {/* SOCIAL HISTORY SECTION */}
      <Card className="border-slate-200 shadow-sm bg-white overflow-visible dark:border-slate-800 dark:bg-slate-900">
        <CardHeader className="bg-slate-50/50 border-b py-3 flex flex-row flex-wrap items-center justify-between gap-2 dark:bg-slate-900 dark:border-slate-800">
          <CardTitle className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 dark:text-slate-300">
            Social Determinants
          </CardTitle>
          {onOpenPatientInfo && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onOpenPatientInfo}
              className="h-7 shrink-0 border-slate-300 bg-white px-2.5 text-[9px] font-black uppercase tracking-wide text-slate-700 hover:bg-slate-100 dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100 dark:hover:bg-slate-700"
            >
              Edit
            </Button>
          )}
        </CardHeader>
        <CardContent className="pt-4 space-y-4 dark:bg-slate-900">
          <div className="flex items-start gap-3">
            <Home className="h-4 w-4 text-slate-400 mt-0.5 dark:text-slate-500" />
            <div>
              <p className="text-[9px] font-black uppercase text-slate-400 dark:text-slate-500">Living Situation</p>
              <p className="text-sm font-medium text-slate-700 dark:text-slate-100">{social?.livingSituation || "Not Documented"}</p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <Cigarette className="h-4 w-4 text-slate-400 mt-0.5 dark:text-slate-500" />
            <div>
              <p className="text-[9px] font-black uppercase text-slate-400 dark:text-slate-500">Tobacco Use</p>
              <p className="text-sm font-medium text-slate-700 dark:text-slate-100">{social?.smokingStatus || "Unknown"}</p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <Wine className="h-4 w-4 text-slate-400 mt-0.5 dark:text-slate-500" />
            <div>
              <p className="text-[9px] font-black uppercase text-slate-400 dark:text-slate-500">Alcohol Use</p>
              <p className="text-sm font-medium text-slate-700 dark:text-slate-100">{social?.alcoholUse || "Unknown"}</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* CARE CHECKLIST SECTION */}
      <Card className="border-emerald-100 shadow-md bg-white overflow-visible dark:border-emerald-800/50 dark:bg-slate-900">
        <CardHeader className="bg-emerald-50/50 border-b py-3 flex flex-row flex-wrap items-center justify-between gap-2 dark:bg-emerald-500/10 dark:border-emerald-800/40">
          <CardTitle className="text-[10px] font-black uppercase tracking-[0.2em] text-emerald-700 flex items-center gap-2 dark:text-emerald-300">
            <ClipboardCheck className="h-4 w-4" /> Care Checklist
          </CardTitle>
          <div className="flex items-center gap-1.5 shrink-0">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleClearCompleted}
              disabled={checklistSummary.completed === 0}
              className="h-7 border-emerald-200 bg-white text-[9px] font-black uppercase tracking-wide text-emerald-700 hover:bg-emerald-50 disabled:opacity-50 dark:border-emerald-700 dark:bg-slate-800 dark:text-emerald-200 dark:hover:bg-emerald-500/20"
            >
              <CheckCircle2 className="mr-1 h-3.5 w-3.5" /> Clear Done
            </Button>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => setAddingTask((prev) => !prev)}
              className="h-7 border-emerald-200 bg-white text-[9px] font-black uppercase tracking-wide text-emerald-700 hover:bg-emerald-50 dark:border-emerald-700 dark:bg-slate-800 dark:text-emerald-200 dark:hover:bg-emerald-500/20"
            >
              <Plus className="mr-1 h-3.5 w-3.5" /> Add
            </Button>
          </div>
        </CardHeader>
        <CardContent className="pt-4 space-y-4 dark:bg-slate-900">
          <div className="space-y-2 rounded-xl border border-emerald-100 bg-emerald-50/50 p-3 dark:border-emerald-800/40 dark:bg-emerald-500/10">
            <div className="flex items-center justify-between">
              <p className="text-[10px] font-black uppercase tracking-wide text-emerald-700 dark:text-emerald-300">
                Checklist Progress
              </p>
              <p className="text-[10px] font-bold text-emerald-700 dark:text-emerald-300">
                {checklistSummary.completed}/{checklistSummary.total}
              </p>
            </div>
            <div className="h-1.5 overflow-hidden rounded-full bg-emerald-100 dark:bg-emerald-900/40">
              <div className="h-full bg-emerald-500 transition-all" style={{ width: `${checklistSummary.percent}%` }} />
            </div>
            <p className="text-[10px] font-semibold text-emerald-700/80 dark:text-emerald-300/80">
              {checklistSummary.pending} pending task{checklistSummary.pending === 1 ? "" : "s"}
            </p>
          </div>

          {addingTask && (
            <div className="space-y-2 rounded-xl border border-slate-200 bg-slate-50 p-3 dark:border-slate-700 dark:bg-slate-800">
              <Input
                value={newTaskText}
                onChange={(event) => setNewTaskText(event.target.value)}
                placeholder="Add a custom care task"
                className="text-xs"
                maxLength={140}
                onKeyDown={(event) => {
                  if (event.key === "Enter") {
                    event.preventDefault();
                    void handleCreateTask();
                  }
                }}
              />
              <div className="flex justify-end gap-2">
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    setAddingTask(false);
                    setNewTaskText("");
                  }}
                  className="h-7 text-[10px] font-black uppercase"
                >
                  Cancel
                </Button>
                <Button
                  type="button"
                  size="sm"
                  onClick={() => void handleCreateTask()}
                  className="h-7 bg-emerald-600 text-[10px] font-black uppercase hover:bg-emerald-700"
                >
                  Add Task
                </Button>
              </div>
            </div>
          )}

          <div className="space-y-3">
            {tasks?.map((task) => (
              <div key={task._id} className="flex items-center justify-between gap-2 group rounded-lg border border-transparent px-1 py-1 hover:border-slate-200 dark:hover:border-slate-700">
                <div className="flex items-start space-x-3 min-w-0">
                  <Checkbox
                    id={task._id}
                    checked={task.completed}
                  onCheckedChange={() => handleToggle(task._id)}
                  className="border-slate-300 data-[state=checked]:bg-emerald-500 data-[state=checked]:border-emerald-500"
                />
                  <div className="min-w-0 space-y-1">
                    <label
                      htmlFor={task._id}
                      className={`text-xs font-bold leading-none transition-colors cursor-pointer truncate block ${
                        task.completed ? "text-slate-400 line-through dark:text-slate-500" : "text-slate-700 dark:text-slate-100"
                      }`}
                    >
                      {task.item}
                    </label>
                    {task.completed && task.completedBy && (
                      <p className="text-[9px] font-semibold text-emerald-700/80 dark:text-emerald-300/80 truncate">
                        Completed by {task.completedBy}
                      </p>
                    )}
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => void handleRemoveTask(task._id)}
                  className="opacity-0 group-hover:opacity-100 transition-opacity text-slate-400 hover:text-rose-600 dark:text-slate-500 dark:hover:text-rose-400"
                  aria-label="Remove checklist item"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            ))}
            {(!tasks || tasks.length === 0) && (
              <p className="text-[10px] text-slate-400 italic text-center py-4 dark:text-slate-500">No tasks assigned for this encounter.</p>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

