"use client";

import { useState } from "react";
import { useMutation } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { 
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter 
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { 
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue 
} from "@/components/ui/select";
import { Scan, Radio, Save, AlertCircle } from "lucide-react";
import { toast } from "sonner";

export default function PlaceImagingOrder({
  encounterId,
  orderedBy,
}: {
  encounterId: Id<"encounters">;
  orderedBy?: string;
}) {
  const [open, setOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  
  const [studyName, setStudyName] = useState("");
  const [modality, setModality] = useState("X-Ray");
  const [priority, setPriority] = useState("Routine");
  const [reason, setReason] = useState("");

  const createOrder = useMutation(api.imaging.createOrder);

  const handleSubmit = async () => {
    if (!studyName || !reason) return;
    setIsSaving(true);
    
    try {
      await createOrder({
        encounterId,
        studyName,
        modality,
        reason,
        priority,
        orderedBy,
      });
      toast.success("Radiology Order Placed", {
        description: `${studyName} has been sent to the imaging queue.`
      });
      setOpen(false);
      setStudyName("");
      setReason("");
    } catch (e) {
      toast.error("Order Failed", { description: "Clinical system error." });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" className="bg-blue-600 hover:bg-blue-700 text-[10px] font-black uppercase tracking-widest gap-2 h-8 px-4">
          <Radio className="h-3.5 w-3.5" /> New Order
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-106.25 rounded-3xl">
        <DialogHeader>
          <DialogTitle className="text-sm font-black uppercase tracking-[0.2em] flex items-center gap-2">
            <Scan className="h-4 w-4 text-blue-600" /> CPOE: Radiology
          </DialogTitle>
        </DialogHeader>

        <div className="grid gap-4 py-4">
          <div className="space-y-2">
            <Label className="text-[10px] font-black uppercase text-slate-400 ml-1">Study Description</Label>
            <Input 
              placeholder="e.g., CT Head w/o Contrast" 
              className="h-10 text-sm font-bold bg-slate-50 border-none rounded-xl"
              value={studyName}
              onChange={(e) => setStudyName(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label className="text-[10px] font-black uppercase text-slate-400 ml-1">Modality</Label>
              <Select value={modality} onValueChange={setModality}>
                <SelectTrigger className="bg-slate-50 border-none rounded-xl h-10 font-bold text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="X-Ray">X-Ray</SelectItem>
                  <SelectItem value="CT">CT Scan</SelectItem>
                  <SelectItem value="MRI">MRI</SelectItem>
                  <SelectItem value="US">Ultrasound</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label className="text-[10px] font-black uppercase text-slate-400 ml-1">Priority</Label>
              <Select value={priority} onValueChange={setPriority}>
                <SelectTrigger className={`border-none rounded-xl h-10 font-bold text-xs ${priority === 'STAT' ? 'bg-red-50 text-red-600' : 'bg-slate-50'}`}>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Routine">Routine</SelectItem>
                  <SelectItem value="STAT">STAT (Urgent)</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label className="text-[10px] font-black uppercase text-slate-400 ml-1">Clinical Indication</Label>
            <Input 
              placeholder="e.g., Rule out acute hemorrhage" 
              className="h-10 text-sm bg-slate-50 border-none rounded-xl italic"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
            />
          </div>
        </div>

        <DialogFooter>
          <Button 
            onClick={handleSubmit} 
            disabled={isSaving || !studyName || !reason}
            className="w-full bg-slate-900 hover:bg-black text-white font-black uppercase text-[10px] tracking-widest h-12 rounded-2xl gap-2 shadow-lg focus-visible:ring-2 focus-visible:ring-blue-500 dark:bg-blue-500 dark:hover:bg-blue-400 dark:text-slate-950"
          >
            {isSaving ? "Submitting..." : <><Save className="h-4 w-4" /> Place Order</>}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useUser } from "@clerk/nextjs";
import { AlertCircle, Lock } from "lucide-react";

interface RoleGateProps {
  children: React.ReactNode;
  allowedRole: "doctor" | "nurse" | "admin";
}

export default function RoleGate({ children, allowedRole }: RoleGateProps) {
  const { user, isLoaded } = useUser();

  if (!isLoaded) return null;

  // Check the publicMetadata we set in the Clerk Dashboard
  const userRole = user?.publicMetadata?.role as string;

  // Admin is a superrole — bypass all role gates
  if (userRole !== allowedRole && userRole !== "admin") {
    return (
      <div className="p-6 border-2 border-dashed border-red-200 rounded-xl bg-red-50 flex flex-col items-center text-center space-y-3">
        <div className="p-3 bg-red-100 rounded-full text-red-600">
          <Lock className="h-6 w-6" />
        </div>
        <div>
          <h3 className="text-lg font-bold text-red-900">Privilege Restricted</h3>
          <p className="text-sm text-red-700 max-w-xs">
            This clinical action requires <strong>{allowedRole}</strong> credentials. 
            Your current role is logged as <strong>{userRole || "Guest"}</strong>.
          </p>
        </div>
      </div>
    );
  }

  return <>{children}</>;
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ClipboardCopy, MessageSquare, AlertTriangle, Activity, CheckCircle2, Sparkles } from "lucide-react";
import { toast } from "sonner";
import { Button } from "./ui/button";
import { useMemo, useState } from "react";

// Define strict types for the SBAR data
interface SBARProps {
  patient: {
    name: string;
    mrn: string;
    dob: string;
    allergies: string[];
    codeStatus?: string;
  };
  encounter: {
    chiefComplaint: string;
    vitals: {
      bp?: string;
      hr?: number;
      spO2?: number;
    };
  };
  gcs?: number | null;
  criticalLabs: Array<{ testName: string }>;
}

export default function SBARHandoff({ patient, encounter, gcs, criticalLabs }: SBARProps) {
  const [aiRecommendation, setAiRecommendation] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [isCopying, setIsCopying] = useState(false);
  const [copied, setCopied] = useState(false);

  const sbarCopyText = useMemo(() => {
    const allergyText = patient.allergies.length > 0 ? patient.allergies.join(", ") : "No known allergies";
    const criticalLabText = criticalLabs.length > 0 ? criticalLabs.map((lab) => lab.testName).join(", ") : "None reported";
    const recommendationText =
      aiRecommendation ||
      "Continue monitoring q4h vitals and reassess for worsening respiratory or neurologic status.";

    return [
      "SBAR CLINICAL HANDOFF",
      `Patient: ${patient.name}`,
      `MRN: ${patient.mrn}`,
      `DOB: ${patient.dob || "N/A"}`,
      "",
      "S - Situation",
      `Chief complaint: ${encounter.chiefComplaint || "N/A"}`,
      `Current vitals: BP ${encounter.vitals.bp ?? "N/A"}, HR ${encounter.vitals.hr ?? "N/A"}, SpO2 ${encounter.vitals.spO2 ?? "N/A"}%`,
      "",
      "B - Background",
      `Code status: ${patient.codeStatus ?? "Full Code"}`,
      `Allergies: ${allergyText}`,
      `Critical labs: ${criticalLabText}`,
      "",
      "A - Assessment",
      `GCS: ${gcs ?? "Not documented"}`,
      "Escalation risks: Monitor oxygenation, hemodynamics, and lab follow-up.",
      "",
      "R - Recommendation",
      recommendationText,
      "",
      `Generated: ${new Date().toLocaleString()}`,
    ].join("\n");
  }, [patient, encounter, gcs, criticalLabs, aiRecommendation]);

  const copyToClipboard = async (text: string) => {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.opacity = "0";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();

    const success = document.execCommand("copy");
    document.body.removeChild(textArea);

    if (!success) {
      throw new Error("Clipboard copy failed");
    }
  };

  const handleCopy = async () => {
    if (isCopying) return;

    setIsCopying(true);
    try {
      await copyToClipboard(sbarCopyText);
      setCopied(true);
      toast.success("SBAR handoff copied to clipboard.");
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error("Unable to copy SBAR handoff.");
    } finally {
      setIsCopying(false);
    }
  };

  const generateRecommendation = () => {
    setIsGenerating(true);
    // Clinical Logic Simulation
    setTimeout(() => {
      let rec = "Continue monitoring q4h vitals. ";
      if (gcs && gcs <= 8) rec = "CRITICAL: Protect airway. Evaluate for immediate intubation. ";
      if (encounter.vitals.spO2 && encounter.vitals.spO2 < 92) rec += "Titrate O2 to maintain >94%. ";
      if (criticalLabs.length > 0) rec += `Follow up on abnormal ${criticalLabs[0].testName}.`;
      
      setAiRecommendation(rec);
      setIsGenerating(false);
      toast.info("Clinical recommendation generated");
    }, 800);
  };

  return (
    <Card className="border-slate-200 shadow-xl rounded-[2rem] overflow-hidden bg-white">
      <CardHeader className="bg-slate-50 border-b flex flex-row items-center justify-between p-6">
        <CardTitle className="text-xs font-black uppercase tracking-widest text-slate-500 flex items-center gap-2">
          <MessageSquare className="h-4 w-4 text-blue-500" /> Clinical SBAR Handoff
        </CardTitle>
        <Button variant="ghost" size="sm" onClick={handleCopy} disabled={isCopying} className="h-7 text-[9px] font-black uppercase text-blue-600">
          <ClipboardCopy className="h-3.5 w-3.5 mr-1" /> {copied ? "Copied" : isCopying ? "Copying" : "Copy"}
        </Button>
      </CardHeader>
      
      <CardContent className="p-6 space-y-6">
        {/* S, B, A Sections as before... */}

        {/* R: RECOMMENDATION with AI */}
        <section className="space-y-3">
          <div className="flex justify-between items-center">
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">R: Recommendation</h4>
            <Button 
              variant="ghost" 
              size="sm" 
              onClick={generateRecommendation}
              disabled={isGenerating}
              className="h-6 text-[8px] font-black uppercase text-purple-600 gap-1 hover:bg-purple-50"
            >
              <Sparkles className={`h-3 w-3 ${isGenerating ? 'animate-spin' : ''}`} /> 
              {aiRecommendation ? "Regenerate" : "AI Suggest"}
            </Button>
          </div>
          <div className="p-4 rounded-2xl bg-slate-50 border border-slate-100 min-h-15">
             <p className="text-xs font-medium text-slate-600 italic leading-relaxed">
               {aiRecommendation || "Select 'AI Suggest' to generate a clinical recommendation based on current data."}
             </p>
          </div>
        </section>

        {/* SHIFT CHANGE CHECKLIST */}
        <section className="pt-4 border-t border-dashed border-slate-200 space-y-3">
          <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
            <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" /> CCMA Sign-Off Checklist
          </h4>
          <div className="grid grid-cols-1 gap-2">
            {[
              "IV Site Patent & Dressing Intact",
              "Call Light Within Reach",
              "Side Rails x2 Up",
              "Final Set of Vitals Charted"
            ].map((item) => (
              <label key={item} className="flex items-center gap-3 p-2 hover:bg-slate-50 rounded-lg cursor-pointer transition-colors border border-transparent hover:border-slate-100">
                <input type="checkbox" className="rounded-md border-slate-300 text-blue-600 focus:ring-blue-500 h-4 w-4" />
                <span className="text-[11px] font-bold text-slate-600">{item}</span>
              </label>
            ))}
          </div>
        </section>
      </CardContent>
    </Card>
  );
}

"use client";

import React from "react";
import { useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Card, CardContent } from "@/components/ui/card";
import { 
  Users, 
  LogOut, 
  Clock, 
  AlertTriangle, 
  GitPullRequest, 
  Activity,
  Stethoscope,
  TrendingDown
} from "lucide-react";
import { 
  Area, 
  AreaChart, 
  Cell, 
  Pie, 
  PieChart, 
  ResponsiveContainer, 
  Tooltip 
} from "recharts";
import { usePresentationMode } from "@/lib/hooks/usePresentationMode";

// --- Types to resolve ESLint 'any' errors ---

interface HighRiskPatient {
  name: string;
  issue: string;
  location: string;
}

interface AcuityData {
  name: string;
  value: number;
  fill: string;
}

interface TrendPoint {
  value: number;
}

interface MetricProps {
  label: string;
  value: string | number;
  icon: React.ReactNode;
  color: string;
  subtitle?: React.ReactNode;
  alert?: boolean;
  active?: boolean;
  children?: React.ReactNode;
}

interface ShiftSummaryProps {
  onFilterChange: (filter: string | null) => void;
  activeFilter: string | null;
}

export default function ShiftSummary({ onFilterChange, activeFilter }: ShiftSummaryProps) {
  const metrics = useQuery(api.encounters.getShiftMetrics);
  const { isDemoMode } = usePresentationMode();

  const formatPatientName = (name: string) => {
    if (!isDemoMode) return name;

    const parts = name.trim().split(/\s+/);
    if (parts.length > 1) {
      return `${parts[0][0]}. ${parts[1]}`;
    }
    return `Patient-${name.length}${name.charCodeAt(0)}`;
  };

  if (!metrics) return (
    <div className="grid grid-cols-1 md:grid-cols-5 gap-4 mb-8 opacity-50">
      {[...Array(5)].map((_, i) => (
        <div key={i} className="h-24 rounded-3xl bg-slate-100 animate-pulse dark:bg-slate-800" />
      ))}
    </div>
  );

  return (
    <div className="space-y-4 mb-8">
      {/* 1. HIGH RISK VITALS TICKER */}
      {metrics?.highRiskPatients && metrics.highRiskPatients.length > 0 && (
        <div className="mb-6 overflow-hidden rounded-xl bg-red-600 py-2 shadow-lg shadow-red-200 dark:shadow-red-950/40">
          <div className="flex animate-marquee whitespace-nowrap items-center">
            {[...metrics.highRiskPatients, ...metrics.highRiskPatients].map((p, i) => (
              <span key={i} className="mx-8 flex items-center gap-2 text-white text-[10px] font-black uppercase tracking-tighter">
                <Activity className="h-3 w-3 animate-pulse" />
                CRITICAL VITALS: {formatPatientName(p.name)} ({p.location}) {isDemoMode ? "- Sensitive details hidden" : `- ${p.issue}`}
              </span>
            ))}
          </div>
        </div>
      )}

      <div className="flex flex-col lg:flex-row gap-4">
        {/* 2. THE METRIC CARDS (Left Side) */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 grow">
          
          <MetricCard 
            label="Staff Ratio" 
            value={`1:${metrics.staffRatio}`} 
            icon={<Stethoscope className="h-5 w-5 text-indigo-600" />} 
            color="bg-indigo-50 dark:bg-indigo-500/15"
            alert={metrics.staffRatio > 6}
            subtitle={metrics.staffRatio > 6 ? "Critical Ratio" : "Safe"}
          />

          <MetricCard 
            label="Avg TTP" 
            value={`${metrics.avgTTP}m`} 
            icon={<Activity className="h-5 w-5 text-orange-600" />} 
            color="bg-orange-50 dark:bg-orange-500/15"
            alert={metrics.avgTTP > metrics.ttpTarget}
            subtitle={
              <div className="flex items-center gap-1">
                <TrendingDown className="h-3 w-3" />
                <span>Goal: {metrics.ttpTarget}m</span>
              </div>
            }
          />

          <MetricCard 
            label="Avg LOS" 
            value={`${metrics.avgLOS}m`} 
            icon={<Clock className="h-5 w-5 text-purple-600" />} 
            color="bg-purple-50 dark:bg-purple-500/15"
            alert={metrics.avgLOS > 240}
          >
            <div className="h-8 w-full mt-2">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={metrics.losTrend as TrendPoint[]}>
                  <Area type="monotone" dataKey="value" stroke="#9333ea" fill="#f3e8ff" strokeWidth={2} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </MetricCard>

          {/* INTERACTIVE CARDS */}
          <div onClick={() => onFilterChange(activeFilter === "Bottle-Neck" ? null : "Bottle-Neck")} className="cursor-pointer">
            <MetricCard 
              label="Bottle-Neck" 
              value={metrics.bottleneckStatus} 
              icon={<GitPullRequest className="h-5 w-5 text-amber-600" />} 
              color="bg-amber-50 dark:bg-amber-500/15"
              active={activeFilter === "Bottle-Neck"}
              subtitle={`${metrics.bottleneckCount} Patients Stuck`}
            />
          </div>

          <div onClick={() => onFilterChange(activeFilter === "Critical" ? null : "Critical")} className="cursor-pointer">
            <MetricCard 
              label="Critical (ESI 1)" 
              value={metrics.criticalCount} 
              icon={<AlertTriangle className="h-5 w-5 text-red-600" />} 
              color="bg-red-50 dark:bg-red-500/15"
              alert={metrics.criticalCount > 0}
              active={activeFilter === "Critical"}
              subtitle={metrics.criticalCount > 0 ? "Immediate Action" : "Stable"}
            />
          </div>

          <MetricCard 
            label="Total Census" 
            value={metrics.activeCount} 
            icon={<Users className="h-5 w-5 text-blue-600" />} 
            color="bg-blue-50 dark:bg-blue-500/15"
          />
        </div>

        {/* 3. ACUITY PIE CHART (Right Side) */}
        <Card className="w-full overflow-hidden border-none bg-white shadow-sm dark:bg-slate-900 lg:w-72">
          <CardContent className="p-4 flex flex-col h-full">
            <p className="mb-2 text-[9px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Acuity Mix</p>
            <div className="h-32 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={metrics.acuityDist as AcuityData[]}
                    innerRadius={35}
                    outerRadius={50}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {(metrics.acuityDist as AcuityData[]).map((entry: AcuityData, index: number) => (
                      <Cell key={`cell-${index}`} fill={entry.fill} />
                    ))}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ fontSize: '10px', borderRadius: '8px', border: 'none', fontWeight: 'bold' }}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex flex-wrap justify-center gap-x-3 gap-y-1 mt-2">
              {(metrics.acuityDist as AcuityData[]).map((d: AcuityData) => (
                <div key={d.name} className="flex items-center gap-1">
                  <div className="h-1.5 w-1.5 rounded-full" style={{ backgroundColor: d.fill }} />
                  <span className="text-[8px] font-black uppercase text-slate-500 dark:text-slate-400">{d.name}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>

      <style jsx>{`
        @keyframes marquee {
          0% { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
        .animate-marquee {
          animation: marquee 30s linear infinite;
        }
      `}</style>
    </div>
  );
}



function MetricCard({ label, value, icon, color, subtitle, alert, active, children }: MetricProps) {
  return (
    <Card className={`border-none shadow-sm transition-all duration-300 dark:shadow-none ${
      alert
        ? 'bg-red-50/70 ring-2 ring-red-500 dark:bg-red-950/30'
        : active
          ? 'bg-blue-50/70 ring-2 ring-blue-500 dark:bg-blue-950/30'
          : 'bg-white dark:bg-slate-900'
    }`}>
      <CardContent className="p-4 flex flex-col h-full justify-center">
        <div className="flex items-center gap-4">
          <div className={`p-3 rounded-2xl ${color} shrink-0`}>
            {icon}
          </div>
          <div className="min-w-0 text-left">
            <p className="truncate text-[9px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-400">{label}</p>
            <h3 className={`text-lg font-black leading-none mt-1 capitalize ${
              alert && (label.includes("Critical") || label.includes("Ratio"))
                ? "text-red-600 dark:text-red-400"
                : "text-slate-900 dark:text-slate-100"
            }`}>
              {value}
            </h3>
            {subtitle && (
              <div className="mt-1 truncate text-[9px] font-bold uppercase text-slate-500 dark:text-slate-400">
                {subtitle}
              </div>
            )}
          </div>
        </div>
        {children}
      </CardContent>
    </Card>
  );
}

"use client";

import { useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { 
  Badge 
} from "@/components/ui/badge";
import { 
  Users, 
  Clock, 
  AlertCircle, 
  CheckCircle2, 
  ArrowRightCircle 
} from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";

export default function TrackingBoard() {
  // 1. Fetch all active encounters (those not yet discharged)
  const activeEncounters = useQuery(api.encounters.getActive);

  if (!activeEncounters) {
    return (
      <div className="flex h-64 items-center justify-center">
        <div className="animate-pulse text-slate-400 font-black tracking-widest uppercase text-xs">
          Loading Live Tracking Data...
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-black tracking-tighter text-slate-900 flex items-center gap-2">
          <Users className="h-6 w-6 text-blue-600" />
          ED TRACKING BOARD
        </h2>
        <Badge variant="outline" className="font-mono text-[10px] border-blue-200 text-blue-700 bg-blue-50">
          LIVE UPDATES ENABLED
        </Badge>
      </div>

      <Card className="border-slate-900 border-t-8 shadow-xl overflow-hidden">
        <CardContent className="p-0">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-6 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">Room/Bed</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">Patient Name</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">ESI</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">Status</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">Wait Time</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {activeEncounters.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-slate-400 italic">
                    All beds clear. Department is currently at zero census.
                  </td>
                </tr>
              ) : (
                activeEncounters.map((encounter) => (
                  <tr key={encounter._id} className="hover:bg-slate-50/50 transition-colors group">
                    {/* ROOM NUMBER */}
                    <td className="px-6 py-4">
                      <span className="font-black text-lg text-slate-800 tracking-tighter">
                        {encounter.location || "Triage"}
                      </span>
                    </td>

                    {/* PATIENT INFO */}
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-900">{encounter.patientName}</span>
                        <span className="text-[10px] text-slate-400 font-mono">CC: {encounter.chiefComplaint}</span>
                      </div>
                    </td>

                    {/* ESI ACUITY */}
                    <td className="px-6 py-4">
                      <div className={`
                        inline-flex items-center justify-center h-8 w-8 rounded-full font-black text-sm
                        ${encounter.acuity === 1 ? "bg-red-600 text-white shadow-lg shadow-red-100" : 
                          encounter.acuity === 2 ? "bg-orange-500 text-white" :
                          encounter.acuity === 3 ? "bg-yellow-400 text-slate-900" :
                          "bg-blue-100 text-blue-700"}
                      `}>
                        {encounter.acuity}
                      </div>
                    </td>

                    {/* STATUS BADGE */}
                    <td className="px-6 py-4">
                      <StatusBadge status={encounter.status} />
                    </td>

                    {/* WAIT TIME */}
                    <td className="px-6 py-4 text-slate-500 font-mono text-xs">
                      <WaitTimer startTime={encounter._creationTime} />
                    </td>

                    {/* ACTION */}
                    <td className="px-6 py-4 text-right">
                      <Link href={`/patient/${encounter.patientId}`}>
                        <button className="p-2 hover:bg-blue-50 text-blue-600 rounded-lg transition-all group-hover:translate-x-1">
                          <ArrowRightCircle className="h-5 w-5" />
                        </button>
                      </Link>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </CardContent>
      </Card>
    </div>
  );
}

// Helper: Status Badge Component
function StatusBadge({ status }: { status: string }) {
  const styles: Record<string, string> = {
    waiting: "bg-slate-100 text-slate-600 border-slate-200",
    triage: "bg-blue-100 text-blue-700 border-blue-200",
    "seen-by-doctor": "bg-purple-100 text-purple-700 border-purple-200",
    "labs-pending": "bg-yellow-100 text-yellow-700 border-yellow-200",
    "ready-for-discharge": "bg-emerald-100 text-emerald-700 border-emerald-200 animate-pulse",
  };

  return (
    <Badge variant="outline" className={`capitalize font-black text-[9px] tracking-widest ${styles[status] || styles.waiting}`}>
      {status.replace(/-/g, " ")}
    </Badge>
  );
}

// Helper: Real-time Wait Timer
function WaitTimer({ startTime }: { startTime: number }) {
  // 1. Calculate the initial time immediately so we don't need an effect call on mount
  const getDiff = () => Math.floor((Date.now() - startTime) / 60000);
  
  const [mins, setMins] = useState<number>(getDiff);

  useEffect(() => {
    // 2. The interval handles subsequent updates (asynchronous)
    const timer = setInterval(() => {
      setMins(getDiff());
    }, 60000); 

    return () => clearInterval(timer);
  }, [startTime]); // Only re-run if the patient's check-in time changes

  return (
    <div className="flex items-center gap-1 font-mono text-[11px] font-bold text-slate-500">
      <Clock className="h-3 w-3 text-slate-300" />
      {mins}m
    </div>
  );
}

"use client";

import * as React from "react"; // Explicit React import for type safety
import { useState } from "react";
import { useMutation, useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import { Id } from "@/convex/_generated/dataModel";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { 
  Brain, Wind, Thermometer, CheckCircle2, Save, 
  Lock, UserCircle, Calendar, Edit3 
} from "lucide-react";
import { toast } from "sonner";

export default function TriageAssessment({ encounterId }: { encounterId: Id<"encounters"> }) {
  const existing = useQuery(api.triage.getByEncounter, { encounterId });
  const submitTriage = useMutation(api.triage.submit);

  const [gcs, setGcs] = useState(15);
  const [resps, setResps] = useState("Normal");
  const [skin, setSkin] = useState("Warm/Dry");
  const [isEditing, setIsEditing] = useState(false);

  const handleSave = async () => {
    try {
      await submitTriage({
        encounterId,
        gcsScore: gcs,
        pupils: "PERRL",
        mentalStatus: gcs === 15 ? "Alert/Oriented" : "Altered",
        workOfBreathing: resps,
        lungSounds: "Clear",
        skinTemp: skin.split("/")[0],
        skinCondition: skin.split("/")[1],
        triageNurse: "Sophia R, RN",
      });
      toast.success("Triage Assessment Finalized");
      setIsEditing(false);
    } catch (e) {
      toast.error("Failed to save assessment");
    }
  };

  // --- READ-ONLY VIEW (FINALIZED) ---
  if (existing && !isEditing) {
    return (
      <Card className="border-emerald-100 shadow-sm overflow-hidden bg-white">
        <CardHeader className="bg-emerald-50/50 border-b py-4 flex flex-row items-center justify-between">
          <CardTitle className="text-xs font-black uppercase tracking-[0.2em] text-emerald-700 flex items-center gap-2">
            <Lock className="h-3.5 w-3.5" /> Finalized Triage Record
          </CardTitle>
          <Button 
            variant="ghost" 
            size="sm" 
            className="h-7 text-[9px] font-black uppercase text-slate-400 hover:text-blue-600"
            onClick={() => setIsEditing(true)}
          >
            <Edit3 className="h-3 w-3 mr-1" /> Add Addendum
          </Button>
        </CardHeader>
        <CardContent className="p-0">
          <div className="grid grid-cols-3 divide-x divide-slate-100">
            <div className="p-6 space-y-2">
              <span className="text-[9px] font-black uppercase text-slate-400 block tracking-widest">Neuro / GCS</span>
              <div className="flex items-end gap-2">
                <span className="text-3xl font-black text-slate-800">{existing.gcsScore}</span>
                <Badge variant="default" className={existing.gcsScore <= 8 ? "bg-red-500 text-white" : "bg-emerald-500 text-white"}>
                  {existing.gcsScore === 15 ? "Intact" : "Altered"}
                </Badge>
              </div>
            </div>
            <div className="p-6 space-y-2">
              <span className="text-[9px] font-black uppercase text-slate-400 block tracking-widest">Respiratory</span>
              <p className="text-sm font-bold text-slate-700 uppercase tracking-tight">{existing.workOfBreathing}</p>
              <p className="text-[10px] text-slate-400 font-medium tracking-tight">Lungs: {existing.lungSounds}</p>
            </div>
            <div className="p-6 space-y-2">
              <span className="text-[9px] font-black uppercase text-slate-400 block tracking-widest text-left">Skin / Temp</span>
              <p className="text-sm font-bold text-slate-700 uppercase tracking-tight text-left">
                {existing.skinTemp} / {existing.skinCondition}
              </p>
            </div>
          </div>
          
          <div className="bg-slate-50 p-4 border-t border-slate-100 flex justify-between items-center">
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-1.5">
                <UserCircle className="h-3.5 w-3.5 text-slate-400" />
                <span className="text-[10px] font-black text-slate-600 uppercase">{existing.triageNurse}</span>
              </div>
              <div className="flex items-center gap-1.5">
                <Calendar className="h-3.5 w-3.5 text-slate-400" />
                <span className="text-[10px] font-mono font-bold text-slate-400">
                  {new Date(existing.completedAt).toLocaleString()}
                </span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  // --- EDITABLE VIEW ---
  return (
    <Card className="border-slate-200 shadow-sm overflow-hidden bg-white">
      <CardHeader className="bg-slate-50/50 border-b py-4">
        <CardTitle className="text-xs font-black uppercase tracking-[0.2em] text-slate-500 flex items-center gap-2">
          <CheckCircle2 className="h-4 w-4 text-emerald-500" /> Primary Triage Survey
        </CardTitle>
      </CardHeader>
      <CardContent className="p-6 space-y-8">
        <div className="space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <Brain className="h-4 w-4 text-purple-600" />
            <Label className="text-[10px] font-black uppercase text-slate-400">Neurological (GCS)</Label>
          </div>
          <div className="px-2">
            <div className="flex justify-between mb-6">
              <span className="text-2xl font-black text-slate-800">{gcs}</span>
              <Badge variant="outline" className={gcs <= 8 ? "bg-red-50 text-red-700 border-red-100" : "bg-emerald-50 text-emerald-700"}>
                {gcs <= 8 ? "Severe (Intubate)" : gcs <= 12 ? "Moderate" : "Mild/Normal"}
              </Badge>
            </div>
            <Slider 
              value={[gcs]} 
              onValueChange={(val: number[]) => setGcs(val[0])} 
              max={15} min={3} step={1} 
              className="py-4 cursor-pointer"
            />
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <Wind className="h-4 w-4 text-blue-600" />
            <Label className="text-[10px] font-black uppercase text-slate-400">Respiratory Effort</Label>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {["Normal", "Labored", "Tachypneic"].map((opt) => (
              <Button 
                key={opt}
                variant={resps === opt ? "default" : "outline"}
                className="text-[10px] font-black uppercase h-9"
                onClick={() => setResps(opt)}
              >
                {opt}
              </Button>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <Thermometer className="h-4 w-4 text-orange-500" />
            <Label className="text-[10px] font-black uppercase text-slate-400">Skin Condition</Label>
          </div>
          <div className="grid grid-cols-2 gap-2">
            {["Warm/Dry", "Cool/Clammy", "Hot/Dry", "Cold/Mottled"].map((opt) => (
              <Button 
                key={opt}
                variant={skin === opt ? "default" : "outline"}
                className="text-[10px] font-black uppercase h-9"
                onClick={() => setSkin(opt)}
              >
                {opt}
              </Button>
            ))}
          </div>
        </div>

        <div className="flex gap-2">
          {isEditing && (
            <Button 
              variant="outline"
              className="flex-1 text-[10px] font-black uppercase h-12 rounded-xl"
              onClick={() => setIsEditing(false)}
            >
              Cancel
            </Button>
          )}
          <Button 
            onClick={handleSave}
            className="flex-[2] bg-slate-900 hover:bg-black text-white font-black uppercase text-[10px] tracking-[0.2em] h-12 rounded-xl gap-2"
          >
            <Save className="h-4 w-4" /> {isEditing ? "Update Assessment" : "Finalize Assessment"}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

